ALTER TABLE "ai_thread_entries" ADD CONSTRAINT "ai_thread_entries_content_by_kind" CHECK (
    jsonb_typeof("ai_thread_entries"."content") = 'object' and case "ai_thread_entries"."kind"
      when 'user' then jsonb_path_exists("ai_thread_entries"."content", '$ ? (exists(@.keyvalue()) && !exists(@.keyvalue() ? (!(@.key == $ks1))) || exists(@.keyvalue()) && !exists(@.keyvalue() ? (!(@.key == $ks2))))', '{"ks1":["text","section"],"ks2":["action","direction"]}', true)
      when 'assistant' then jsonb_path_exists("ai_thread_entries"."content", '$ ? (exists(@.action))', '{}', true) and not jsonb_path_exists("ai_thread_entries"."content", '$.keyvalue() ? (!(@.key == $ks))', '{"ks":["action","text","proposal","stale_reason"]}', true)
      when 'event' then jsonb_path_exists("ai_thread_entries"."content", '$ ? (exists(@.action))', '{}', true) and not jsonb_path_exists("ai_thread_entries"."content", '$.keyvalue() ? (!(@.key == $ks))', '{"ks":["action","usage","dmp_id"]}', true)
    end
  );--> statement-breakpoint
